def normalize_language(value: str) -> str:
    if not value:
        return "en"

    if isinstance(value, list):
        value = value[0] if value else "en"

    value = str(value).lower()

    if value.startswith("es"):
        return "es"
    if value.startswith("pt"):
        return "pt"
    if value.startswith("en"):
        return "en"

    return "en"


def get_browser_locale() -> str:
    try:
        locale = st.context.locale
        return locale or "en-US"
    except Exception:
        return "en-US"


def set_lang(lang: str):
    st.query_params["lang"] = lang
    st.rerun()


url_lang = st.query_params.get("lang", None)
browser_locale = get_browser_locale()
current_lang = normalize_language(url_lang or browser_locale)
