        with st.expander(T["view_files"]):
            for i, pdf in enumerate(st.session_state["lista_pdfs"], start=1):
                st.write(f"{i}. {pdf}")

        if st.session_state["errores"]:
            with st.expander(T["view_errors"]):
                for pdf, error in st.session_state["errores"]:
                    st.write(f"**{pdf}**")
                    st.code(error)


